def solve(s: str):
    """Run-length encoding: return list of [char, count] for each consecutive run."""
    if not s:
        return []
    res = []
    current = s[0]
    count = 1
    for ch in s[1:]:
        if ch == current:
            count += 1
        else:
            res.append([current, count])
            current = ch
            count = 1
    res.append([current, count])
    return res

