    """Count the number of islands in a 2D grid of 0s and 1s.
    An island is a group of horizontally or vertically adjacent 1s.
    """
    if not grid:
        return 0
    m, n = len(grid), len(grid[0])
    visited = [[False] * n for _ in range(m)]
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
