def solve(tokens):
    """Evaluate an RPN expression given as list of string tokens.
    Supported operators: '+', '-', '*', '/'. Division truncates toward zero.
    Numbers may be negative or positive integers.
    """
    stack = []
    ops = {'+', '-', '*', '/'}
    for token in tokens:
        if token not in ops:
            # parse integer, allow leading +/-
            stack.append(int(token))
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = a + b
            elif token == '-':
                res = a - b
            elif token == '*':
                res = a * b
            else:  # division
                # Python's int(a / b) truncates toward zero
                res = int(a / b)
            stack.append(res)
    return stack[0] if stack else 0

