            # string of characters
            normalized.append([int(ch) for ch in row if ch in '01'])
        else:
            # assume iterable of elements
            new_row = []
            for cell in row:
                if isinstance(cell, str):
                    # single character string
                    new_row.append(int(cell))
                else:
                    new_row.append(int(cell))
            normalized.append(new_row)
    n = len(normalized)
    visited = [ [False]*len(r) for r in normalized ]
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if x < 0 or x >= n:
                continue
            if y < 0 or y >= len(normalized[x]):
                continue
            if visited[x][y] or normalized[x][y] == 0:
                continue
            visited[x][y] = True
            stack.extend([(x-1, y), (x+1, y), (x, y-1), (x, y+1)])
    count = 0
    for i in range(n):
        for j in range(len(normalized[i])):
